#include "v42_lapm.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
int main(void){uint8_t bits[V42_HDLC_MAX_BITS];struct v42_lapm_frame f;static const uint8_t p[]={1,2,0x7e,0xff};size_t n=v42_lapm_encode_i(1,127,73,1,p,sizeof p,bits,sizeof bits);assert(n&&v42_lapm_decode(bits,n,&f)==0);assert(f.type==V42_LAPM_I&&f.dlci==0&&f.cr==1&&f.ns==127&&f.nr==73&&f.pf==1&&f.info_count==sizeof p&&!memcmp(f.info,p,sizeof p));enum v42_lapm_type types[]={V42_LAPM_RR,V42_LAPM_RNR,V42_LAPM_REJ,V42_LAPM_SREJ};for(size_t i=0;i<4;i++){n=v42_lapm_encode_s(types[i],0,126,1,bits,sizeof bits);assert(n&&v42_lapm_decode(bits,n,&f)==0&&f.type==types[i]&&f.nr==126);assert(f.pf==(types[i]==V42_LAPM_SREJ?0:1));}n=v42_lapm_encode_u(V42_LAPM_SABME,1,1,0,0,bits,sizeof bits);assert(n&&v42_lapm_decode(bits,n,&f)==0&&f.type==V42_LAPM_U&&f.u_control==V42_LAPM_SABME&&f.pf);n=v42_lapm_encode_u(V42_LAPM_UA,0,1,0,0,bits,sizeof bits);assert(n&&v42_lapm_decode(bits,n,&f)==0&&f.u_control==V42_LAPM_UA&&f.pf);puts("V.42 LAPM modulo-128 I/S and SABME/UA frames pass");return 0;}
